// PARTE 1 — Verificar un archivo contra el hash que publicó su autor
    // ========================================================================

    // Un hash es una "huella digital" del contenido: si cambia UN solo byte,
    // la huella cambia por completo.
    static byte[] sha256(Path file) throws IOException, GeneralSecurityException {
        return MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file));
    }

    // Compara contra el hash publicado. isEqual compara en tiempo constante
    // (buena práctica al comparar valores de seguridad).
    static boolean matchesPublishedHash(Path file, String publishedHex)
            throws IOException, GeneralSecurityException {
        byte[] expected = HexFormat.of().parseHex(publishedHex);
        return MessageDigest.isEqual(sha256(file), expected);
    }

