// PARTE 2 — Registro de auditoría a prueba de alteraciones
    // ========================================================================

    // Cada entrada guarda el MAC de la anterior (prevMac): forman una cadena.
    record Entry(int index, String actor, String action, String prevMac, String mac) { }

    static class AuditLog {
        private static final String GENESIS = "GENESIS";
        private final byte[] key;                       // clave secreta, guardada FUERA de la base
        private final List<Entry> entries = new ArrayList<>();

        AuditLog(byte[] key) { this.key = key; }

        static AuditLog fromEntries(byte[] key, List<Entry> list) {
            AuditLog log = new AuditLog(key);
            log.entries.addAll(list);
            return log;
        }

        void append(String actor, String action) throws GeneralSecurityException {
            String prev = entries.isEmpty() ? GENESIS : entries.get(entries.size() - 1).mac();
            int index = entries.size();
            entries.add(new Entry(index, actor, action, prev, mac(index, actor, action, prev)));
        }

        // Devuelve el índice de la primera entrada rota, o -1 si todo está íntegro.
        int firstBrokenEntry() throws GeneralSecurityException {
            String expectedPrev = GENESIS;
            for (Entry e : entries) {
                boolean linked = e.prevMac().equals(expectedPrev);          // ¿encaja con la anterior?
                boolean authentic = same(e.mac(), mac(e.index(), e.actor(), e.action(), e.prevMac()));
                if (!linked || !authentic) return e.index();
                expectedPrev = e.mac();
            }
            return -1;
        }

        List<Entry> snapshot() { return Collections.unmodifiableList(entries); }

        // HMAC-SHA256: un hash que además necesita la clave. Sin la clave, alguien que
        // edite la base no puede recalcular un MAC válido. (Un hash simple no alcanza:
        // cualquiera puede recalcularlo.)
        // Simplificación didáctica: el separador "|" podría confundirse si un campo lo
        // contiene; en producción se serializan los campos con longitud o en JSON.
        private String mac(int index, String actor, String action, String prev)
                throws GeneralSecurityException {
            Mac hmac = Mac.getInstance("HmacSHA256");
            hmac.init(new SecretKeySpec(key, "HmacSHA256"));
            String data = index + "|" + actor + "|" + action + "|" + prev;
            return HexFormat.of().formatHex(hmac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
        }

        private static boolean same(String a, String b) {
            return MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8), b.getBytes(StandardCharsets.UTF_8));
        }
    }
